course=read('course.json');by={x['id']:x for x in course['chapters']};cov=load()
# Put legacy anchors for the three old diagram descriptions beside the actual
# replacement figure, not at the end-of-chapter practice paragraph.
for ident,uid,title in [('feat-missing','6fcdb6510f803e0645','Три состояния одного поля'),
 ('feat-sets','8450c646ad2e3131c0','Множество, мультимножество и последовательность'),
 ('feat-time','f282e851cae3ac4a04','Событие и доступная информация')]:
 u=next(u for u in cov['units'] if u['id']==uid);assert len(u['targets'])==1
 rel=by[ident]['path'];text=(ROOT/rel).read_text(encoding='utf8');a,b,part=sections(text)[title]
 cov['spans'][u['targets'][0]].update(start_line=a,end_line=b,sha256=digest(part),destination_section=title)
for span in cov['spans'].values():
 if span['path'] in [by[i]['path'] for i in ids] and span.get('rationale','').startswith('Пакет 02:'):
  span['rationale']=span['rationale'].replace('Пакет 02:','Пакет 03:',1)
save(cov)
scenarios=read('editorial/chapter-scenarios.json')
for ident in ids:
 s=scenarios['chapters'][ident];ch=by[ident];result,definitions,diagram=details[ident]
 s.update(status='authored — пакет 03, приёмка текста отдельно',result=result,definitions_and_formulas=definitions,diagram_narrative=diagram)
 s['markdown']=f'**Учебный вопрос:** {s["question"]}\n\n**Результат:** {result}\n\n**Уровень:** {ch["level"]}. **Предпосылки:** '+(', '.join(ch['prerequisites']) or 'не требуются')+'\n\n**Потребители:** '+(', '.join(ch.get('used_by',[])) or 'завершение прикладной ветки')+'\n\n**Порядок объяснения:**\n\n'+''.join(f'{i}. {v}.\n' for i,v in enumerate(s['steps'],1))+f'\n**Определения, формулы и предпосылки:** {definitions}\n\n**Разобранный пример:** {s["example"]}\n\n**Схемы и разбор:** {diagram}\n\n**Практика и проверка:** {s["practice"]}\n\n**Ограничения:** {s["limitations"]}\n'
write('editorial/chapter-scenarios.json',scenarios)
figures=read('editorial/illustrations.json');paths={p for i in ids for p in by[i]['figures']}
figures['figures']=[x for x in figures['figures'] if x['path'] not in paths]
for p in sorted(paths):
 figures['figures'].append({'path':p,'kind':'original-course-diagram','external_figure':'none','authors':'Авторская схема курса',
  'license':'Лицензия проекта; внешние рисунки не копируются.','production':'tools/draw_batch03_features.py',
  'chapters':[i for i in ids if p in by[i]['figures']],'checked_on':'2026-10-28',
  'source_of_mechanism':'Учебные выводы и примеры главы; ссылки на первичную документацию указаны в редакционном реестре.',
  'changes':'Перерисована русскоязычная предметная схема с объектами, ветвями и расчётом.'})
write('editorial/illustrations.json',figures)
print('Sixteen authored scenarios, sixteen original diagrams, three legacy figure anchors corrected.')
